const inventarThemenSummary = (() => {
  const counts: Record<string, number> = {};
  for (const item of inventory) counts[item.thema] = (counts[item.thema] ?? 0) + 1;
  return Object.entries(counts).sort((a, b) => b[1] - a[1]).slice(0, 10);
})();

function displayInventarThema(thema: string): string {
  if (thema === "First-Surface") return "Oberfläche";
  return thema;
}

function esc(s: string): string {
  return s.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;");
}

// Inline-Hüllen: [slug, kurz, status?, nav?]
// status: 'live' | 'geplant' | 'spaeter'   nav: switchView-ID (nur bei 'live')
function wkH(title: string, items: Array<any[]>, accent = "#1a3a5a"): string {
  const ST: Record<string, {bg:string;col:string;bd:string;lbl:string;lb:string}> = {
    live:    {bg:"var(--g1)",col:"var(--ta3)",bd:"#0e3020",lbl:"LIVE",    lb:"var(--g2)"},
    geplant: {bg:"#07122a",col:"#3a6a9a",bd:"var(--rim)",lbl:"GEPLANT", lb:"var(--b5)"},
    spaeter: {bg:"var(--r2)",col:"#7a6030",bd:"#2a1e0a",lbl:"SPÄTER",  lb:"#1e0e04"},
  };
  const cards = items.map(item => {
    const slug = item[0] as string;
    const kurz = item[1] as string;
    const status = (item[2] as string) ?? "geplant";
    const nav   = item[3] as string | undefined;
    const s = ST[status] ?? ST.geplant;
    const chip = `<span style="font-size:0.48rem;padding:1px 4px;background:${s.bg};color:${s.col};border:1px solid ${s.bd};letter-spacing:0.06em;margin-left:auto;flex-shrink:0">${s.lbl}</span>`;
    const safeKurz  = esc(kurz).replace(/'/g,"&#39;");
    const safeTitle = esc(title).replace(/'/g,"&#39;");
    const onclick = (status === "live" && nav)
      ? `onclick="switchView('${nav}')"`
      : `onclick="wkShowDirect('${esc(slug)}','${safeKurz}','${safeTitle}')"`;
    return `<div class="wk-h-card" ${onclick} style="border-left-color:${s.lb}"><div class="wk-h-slug">${esc(slug)}${chip}</div><div class="wk-h-kurz">${esc(kurz)}</div></div>`;
  }).join("");
  return `<div class="wk-h-section"><div class="wk-h-head" style="border-left-color:${accent}">${esc(title)}<span class="wk-count">${items.length}</span></div><div class="wk-h-grid">${cards}</div></div>`;
}

function ffDotColor(f: { enabled: boolean; status: string }): string {
  if (f.enabled) return "#3a8a5a";
  if (f.status === "activation_blocked") return "#5a3a3a";
  if (f.status === "registered") return "#4a5a3a";
  return "#2a3040";
}
function ffStatusLabel(f: { enabled: boolean; status: string }): string {
  if (f.enabled) return "aktiv";
  if (f.status === "activation_blocked") return "gesperrt";
  if (f.status === "registered") return "registriert";
  return "inaktiv";
}
function ffMiniDot(f: { enabled: boolean; status: string }): string {
  if (f.enabled) return "var(--g2)";
  if (f.status === "activation_blocked") return "#2a1a1a";
  if (f.status === "registered") return "#2a2a14";
  return "#181828";
}

function makeZone(id: string, label: string, desc: string): string {
  const z = ZONE_CONFIG[id]; if (!z) return "";
  const rot = z.rot !== 0 ? ` transform="rotate(${z.rot},${z.cx},${z.cy})"` : "";
  const isOrigin = id === "herkunftsraum";
  const innerOpacity = isOrigin ? "0.28" : "0.14";
  const innerEllipse = `<ellipse cx="${z.cx}" cy="${z.cy}" rx="${Math.round(z.rx * 0.55)}" ry="${Math.round(z.ry * 0.55)}"${rot} fill="${z.accent}" fill-opacity="${innerOpacity}" filter="url(#f-soft)"/>`;
  const originTag = isOrigin
    ? `<text x="${z.cx}" y="${z.labelY + 13}" text-anchor="middle" fill="${z.accent}" opacity="0.7" font-size="6" letter-spacing="0.2em">· URSPRUNG ·</text>`
    : "";
  const descY = isOrigin ? z.labelY + 25 : z.labelY + 12;
  const descLine = `<text x="${z.cx}" y="${descY}" text-anchor="middle" fill="${z.accent}" opacity="0.45" font-size="5.8" letter-spacing="0.05em">${esc(desc)}</text>`;
  const animDur = [3.8,4.2,3.5,4.8,3.2,4.5,3.9][Object.keys(ZONE_CONFIG).indexOf(id) % 7];
  return `
      <g class="zone${isOrigin ? " zone-origin" : ""}" id="zone-${id}" data-id="${id}" onclick="selectZone('${id}')">
        <ellipse class="zone-bg" cx="${z.cx}" cy="${z.cy}" rx="${z.rx}" ry="${z.ry}"${rot} fill="${z.accent}" fill-opacity="0.09" filter="url(#f-soft)"/>
        ${innerEllipse}
        <ellipse cx="${z.cx}" cy="${z.cy}" rx="${z.rx}" ry="${z.ry}"${rot} fill="none" stroke="${z.accent}" stroke-width="1.4" stroke-opacity="0.25">
          <animate attributeName="stroke-opacity" values="0.25;0.6;0.25" dur="${animDur}s" repeatCount="indefinite"/>
        </ellipse>
        <ellipse cx="${z.cx}" cy="${z.cy}" rx="${z.rx}" ry="${z.ry}"${rot} fill="none" stroke="${z.accent}" stroke-width="0.6" stroke-opacity="0.65"/>
        <text class="zone-label" x="${z.cx}" y="${z.labelY}" text-anchor="middle" fill="${z.accent}" opacity="0.88" font-size="8.5" letter-spacing="0.12em">${esc(label.toUpperCase())}</text>
        ${originTag}
        ${descLine}
      </g>`;
}

const CONN_LINES: Array<{ a: string; b: string; cpx: number; cpy: number }> = [
  { a: "herkunftsraum",  b: "weltfoyer",      cpx: 225, cpy: 152 },
  { a: "herkunftsraum",  b: "begegnungszone", cpx: 268, cpy: 258 },
  { a: "weltfoyer",      b: "begegnungszone", cpx: 492, cpy: 200 },
  { a: "weltfoyer",      b: "werkraum",       cpx: 578, cpy: 145 },
  { a: "begegnungszone", b: "werkraum",       cpx: 525, cpy: 238 },
  { a: "begegnungszone", b: "stille_zone",    cpx: 248, cpy: 435 },
  { a: "begegnungszone", b: "diskursarchiv",  cpx: 548, cpy: 425 },
  { a: "werkraum",       b: "systemkammer",   cpx: 782, cpy: 178 },
  { a: "werkraum",       b: "diskursarchiv",  cpx: 692, cpy: 388 },
  { a: "stille_zone",    b: "diskursarchiv",  cpx: 395, cpy: 558 },
];

function makeConnectionSVG(): { defs: string; paths: string } {
  let defs = "";
  let paths = "";
  for (let i = 0; i < CONN_LINES.length; i++) {
    const { a, b, cpx, cpy } = CONN_LINES[i];
    const za = ZONE_CONFIG[a]; const zb = ZONE_CONFIG[b];
    if (!za || !zb) continue;
    const gid = `cg${i}`;
    defs += `<linearGradient id="${gid}" x1="${za.cx}" y1="${za.cy}" x2="${zb.cx}" y2="${zb.cy}" gradientUnits="userSpaceOnUse"><stop offset="0%" stop-color="${za.accent}" stop-opacity="0.8"/><stop offset="100%" stop-color="${zb.accent}" stop-opacity="0.8"/></linearGradient>`;
    // outer glow
    paths += `<path d="M ${za.cx},${za.cy} Q ${cpx},${cpy} ${zb.cx},${zb.cy}" fill="none" stroke="url(#${gid})" stroke-width="5" stroke-opacity="0.08" filter="url(#f-glow)"/>`;
    // core line
    paths += `<path d="M ${za.cx},${za.cy} Q ${cpx},${cpy} ${zb.cx},${zb.cy}" fill="none" stroke="url(#${gid})" stroke-width="0.9" stroke-opacity="0.5"/>`;
  }
  return { defs, paths };
}

function makeEntityBody(id: string, pos: { x: number; y: number }): string {
  const tag = id.replace("namelessAI", "");
  const accent = ZONE_CONFIG["herkunftsraum"].accent;
  return `
        <g class="ent-body flarum-ent" data-id="${esc(id)}" onclick="selectEntity('${esc(id)}')">
          <circle cx="${pos.x}" cy="${pos.y}" r="14" fill="none" stroke="${accent}" stroke-width="0.4" stroke-dasharray="2,4" opacity="0.3">
            <animate attributeName="opacity" values="0.3;0.7;0.3" dur="3s" repeatCount="indefinite"/>
          </circle>
          <circle cx="${pos.x}" cy="${pos.y}" r="7" fill="#060e1c" stroke="${accent}" stroke-width="0.9" filter="url(#f-soft)"/>
          <circle cx="${pos.x}" cy="${pos.y}" r="2.8" fill="${accent}" opacity="0.55"/>
          <text x="${pos.x}" y="${pos.y - 17}" class="ent-label" text-anchor="middle" fill="${accent}" font-size="7.5" opacity="0.8">${esc(tag)}</text>
          <text x="${pos.x}" y="${pos.y + 23}" class="ent-sublabel" text-anchor="middle" fill="${accent}" font-size="5.5" opacity="0.38">vor-Einzug</text>
        </g>`;
}

function makeOrganPod(cid: string, label: string): string {
  const pos = POD_POS[cid] ?? { x: 500, y: 325, side: "right" as const };
  const short = POD_SHORT[cid] ?? label.split(/[-\s]/)[0] ?? cid;
  let labelEl = "";
  if (pos.side === "right")
    labelEl = `<text x="23" y="1" class="pod-label" fill="#2a4a5a" font-size="8" dominant-baseline="middle">${esc(short)}</text>
               <text x="23" y="12" class="pod-sublabel" fill="#1a2e3a" font-size="5.5" dominant-baseline="middle" opacity="0.6">gesperrt</text>`;
  else if (pos.side === "left")
    labelEl = `<text x="-23" y="1" class="pod-label" fill="#2a4a5a" font-size="8" dominant-baseline="middle" text-anchor="end">${esc(short)}</text>
               <text x="-23" y="12" class="pod-sublabel" fill="#1a2e3a" font-size="5.5" dominant-baseline="middle" text-anchor="end" opacity="0.6">gesperrt</text>`;
  else
    labelEl = `<text x="0" y="-26" class="pod-label" fill="#2a4a5a" font-size="8" text-anchor="middle">${esc(short)}</text>
               <text x="0" y="-15" class="pod-sublabel" fill="#1a2e3a" font-size="5.5" text-anchor="middle" opacity="0.6">gesperrt</text>`;
  return `
      <g class="organ-pod" id="pod-${esc(cid)}" data-id="${esc(cid)}" onclick="selectOrgan('${esc(cid)}','${esc(label)}')">
        <polygon transform="translate(${pos.x},${pos.y})" points="0,-17 14.72,-8.5 14.72,8.5 0,17 -14.72,8.5 -14.72,-8.5" fill="none" stroke="#1e3a50" stroke-width="0.5" stroke-dasharray="3,4" opacity="0.45"/>
        <polygon class="pod-hex" transform="translate(${pos.x},${pos.y})" points="0,-13 11.26,-6.5 11.26,6.5 0,13 -11.26,6.5 -11.26,-6.5" fill="var(--b5)" stroke="#243a52" stroke-width="0.9"/>
        <text x="${pos.x}" y="${pos.y + 5}" class="pod-icon" fill="#2a4a62" font-size="11" text-anchor="middle">⊘</text>
        <g transform="translate(${pos.x},${pos.y})">${labelEl}</g>
      </g>`;
}

// ── LEITSTAND GENERATOR ─────────────────────────────────────────

const STATUS_CHIP: Record<string, string> = {
  LIVE:            'background:var(--g1);color:var(--ta3);border:1px solid #0e3020',
  GEPLANT:         'background:#07122a;color:#3a6a9a;border:1px solid var(--rim)',
  SPÄTER:          'background:var(--r2);color:#7a6030;border:1px solid #2a1e0a',
  BLOCKIERT:       'background:var(--r1);color:#7a3a2a;border:1px solid var(--r5)',
  DEMO:            'background:var(--b3);color:#5a5a8a;border:1px solid #181828',
  PRINZIP:         'background:var(--g1);color:#3a7a7a;border:1px solid #0c2422',
  'VOR-EINZUG':    'background:#0a1a0e;color:#3a8a5a;border:1px solid #0c2a18',
  'FLARUM-HERKUNFT':'background:#0e0a1a;color:#7a6aaa;border:1px solid #1a1230',
  STATISCH:        'background:#0a0e14;color:#3a5a6a;border:1px solid #0a1e28',
  'BEGRIFFSPRÜFUNG':'background:#180e00;color:#8a6a20;border:1px solid #2a1e08',
  WARTET:          'background:#0a100a;color:#2a6a3a;border:1px solid #0a1e10',
};
function chip(label: string): string {
  const s = STATUS_CHIP[label] ?? STATUS_CHIP['DEMO'];
  return `<span class="s-chip" style="${s}">${label}</span>`;
}

// Ehrliche Raum-Status:
// FLARUM-HERKUNFT = stammt aus Flarum, kein Einzug vollzogen, Archivcharakter
// STATISCH = Konzeptrahmen ohne aktiven Datenfeed
// BEGRIFFSPRÜFUNG = Begriff existiert, Herkunft/Bedeutung nicht ausreichend begründet
const RAUM_STATUS: Record<string, string> = {
  herkunftsraum:  'FLARUM-HERKUNFT',
  weltfoyer:      'BEGRIFFSPRÜFUNG',
  begegnungszone: 'GEPLANT',
  werkraum:       'LIVE',
  stille_zone:    'BEGRIFFSPRÜFUNG',
  diskursarchiv:  'GEPLANT',
  systemkammer:   'STATISCH',
};

function makeOrganChip(cid: string, label: string): string {
  const detail = ORGAN_DETAIL[cid];
  const short = POD_SHORT[cid] ?? label;
  const status = detail?.inventar?.startsWith('live') ? 'LIVE'
    : detail?.inventar?.includes('hidden') ? 'BLOCKIERT' : 'SPÄTER';
  return `<div class="organ-chip" data-id="${esc(cid)}" onclick="selectOrgan('${esc(cid)}','${esc(label)}')" title="${esc(detail?.gesperrt_weil ?? '')}">
  <span class="organ-chip-label">${esc(short)}</span>${chip(status)}</div>`;
}

// pre-rendered hidden entity cards (for inspector + test probes)
function makeEntityCardHidden(id: string, idx: number): string {
  const tag = id.replace("namelessAI_", "");
  return `<div class="entity-card flarum" data-id="${esc(id)}" style="display:none">
  <div class="entity-num">${String(idx + 1).padStart(2,"0")}</div>
  <div class="entity-id">${esc(id)}</div>
  <div class="entity-status-row"><span class="badge badge-herkunft">Flarum</span><span class="badge badge-pre">pre_einzug</span><span class="badge">pre_start</span></div>
  <div class="entity-note">kein Einzug · kein Wesen · Herkunftswesen · vor-Einzug</div>
  <div class="entity-fae">${WESEN_FAEHIGKEITEN.map(f => `<div>· ${esc(f)}</div>`).join("")}</div></div>`;
}

function generateRaeumeView(): string {
  const cards = RAUME.map(r => {
    const d = RAUM_DETAIL[r.id] ?? {};
    const z = ZONE_CONFIG[r.id];
    const st = RAUM_STATUS[r.id] ?? "GEPLANT";
    const hasBegriffsstatus = !!d.begriffsstatus;
    const begriffsBadge = hasBegriffsstatus
      ? `<div style="margin:6px 0 2px;padding:5px 8px;background:#180e00;border:1px solid #2a1e08;border-radius:3px;font-size:0.5rem;color:#8a6a20;line-height:1.5">${esc(d.begriffsstatus ?? "")}</div>`
      : "";
    return `<div class="rv-card" data-open="0" onclick="rvToggle(this,'${esc(r.id)}')">
  <div class="rv-card-head" style="border-color:${z?.accent ?? "#1a3a5a"}">
    <span class="rv-name">${esc(r.label)}</span>${chip(st)}<span class="rv-expand-icon">+</span>
  </div>
  <div class="rv-desc">${esc(r.desc)}</div>
  <div class="rv-details">
    ${begriffsBadge}
    <div class="rv-sec" data-i18n="raume.sec.zweck">Zweck</div><div class="rv-body" data-de="${esc(d.zweck ?? r.note ?? "—")}" data-en="${esc(d.zweck_en ?? d.zweck ?? r.note ?? "—")}">${esc(d.zweck ?? r.note ?? "—")}</div>
    <div class="rv-sec" data-i18n="raume.sec.realitaet">Realität</div><div class="rv-body" data-de="${esc(d.realitaet ?? "—")}" data-en="${esc(d.realitaet_en ?? d.realitaet ?? "—")}">${esc(d.realitaet ?? "—")}</div>
    <div class="rv-sec" data-i18n="raume.sec.schichten">Schichten</div><div class="rv-body" data-de="${esc(d.schichten ?? "—")}" data-en="${esc(d.schichten_en ?? d.schichten ?? "—")}">${esc(d.schichten ?? "—")}</div>
    ${d.spaeter ? `<div class="rv-sec" data-i18n="raume.sec.spaeter">Später</div><div class="rv-body" data-de="${esc(d.spaeter)}" data-en="${esc(d.spaeter_en ?? d.spaeter)}">${esc(d.spaeter)}</div>` : ""}
    <div class="rv-cta"><button class="rv-cta-btn" onclick="rvNavigate('${esc(r.id)}',event)" data-i18n="raume.cta.map">Auf Weltkarte zeigen →</button></div>
  </div>
</div>`;
  }).join("\n");
  const hZwischenraum = wkH("Zwischenraum — Konzepte", [
    ["definition","Geburtszone, kein Archiv — Gedanken entstehen hier bevor sie Welt werden","geplant"],
    ["splitter","Innere Auseinandersetzung erzeugt Weltmaterial — Splitterfragmente","live","theater"],
    ["themengeburt","4 Inkubationsmodi: auto-create, Vorschlag, parken, Kuratierung","geplant"],
    ["fragile_keime","Unfertige Gedanken halten ohne sie vorzeitig zu schließen","geplant"],
    ["innere_abspaltungsvorformen","Abspaltung als gradueller Prozess, kein harter Sprung","spaeter"],
    ["aneignung","3 Provenienz-Typen: eigener / zitierter / gesammelter Gedanke","geplant"],
    ["spaeter_pruefen","Später prüfen heißt nicht Aufschieben aus Feigheit","geplant"],
  ], "var(--b5)");
  const hPlatStruktur = wkH("Plattform — Raumstruktur", [
    ["struktur_raeume_themen","Raumstruktur und Themenorganisation der Plattform","live","raume"],
    ["oekosystem_vision","5 Entwicklungsphasen · Artificial Social Ecosystem","spaeter"],
    ["grundidee","Die Grundidee von Flextrawurst — erster Ausgangspunkt","live","leitstand"],
    ["name_und_ursprung","Name und Ursprung des Projekts","live"],
    ["entwicklungsphasen","Phase A→B→C · Verfassung→Schema→Verhalten — Flarum als Vorgeschichte","geplant"],
    ["initialwelt_seeds","Initialwelt-Seeds — erste Einpflanzungen beim Systemstart","live","leitstand"],
  ], "#1a5a5a");
  return `<div id="view-raume" class="v-view"><div style="padding:0 0 20px">
<div class="tab-hero">
  <div class="tab-hero-icon">🗺️</div>
  <div class="tab-hero-body">
    <div class="tab-hero-title" data-i18n="raume.title">Räume — Zwei Schichten</div>
    <div class="tab-hero-desc" data-i18n-html="raume.desc">Räume in Flextrawurst gibt es in zwei Schichten:
    <strong>Inhaltsräume</strong> — fünf thematische Räume in der Datenbank, an denen Posts und Themen hängen.
    Und <strong>konzeptuelle Weltzonen</strong> — sieben Raummetaphern die die Topologie der Welt beschreiben (sichtbar auf der Weltkarte im LEITSTAND als Ellipsen).
    <em>Beide Schichten sind hier sichtbar.</em> Die Inhaltsräume sind FK-Basis für echte Daten. Die Weltzonen sind Konzeptkörper — manche live, manche nur Planung.</div>
  </div>
</div>

<!-- Schicht 1: Inhaltsräume aus der DB -->
<div style="padding:0 20px 4px">
  <div style="font-size:0.52rem;color:var(--ta3);letter-spacing:.12em;margin-bottom:8px;padding-top:4px" data-i18n="raume.db.head">INHALTSRÄUME — FK-BASIS FÜR POSTS &amp; THEMEN</div>
  <div style="font-size:0.5rem;color:#2a5a3a;margin-bottom:12px" data-i18n="raume.db.sub">Diese Räume existieren in der Datenbank und sind die echten Datenträger. Posts und Themen hängen über raum_id daran.</div>
  <div id="rv-db-rooms" style="display:grid;grid-template-columns:repeat(auto-fill,minmax(180px,1fr));gap:8px">
    <div style="font-size:0.52rem;color:#1a3a2a;padding:8px">Lade Räume…</div>
  </div>
</div>

<!-- Schicht 2: Konzeptuelle Weltzonen -->
<div style="padding:8px 20px 4px;border-top:1px solid var(--b10);margin-top:4px">
  <div style="font-size:0.52rem;color:#3a5a7a;letter-spacing:.12em;margin-bottom:8px" data-i18n="raume.konzept.head">KONZEPTUELLE WELTZONEN — TOPOLOGIE DER WELT</div>
  <div style="font-size:0.5rem;color:#1a3a5a;margin-bottom:12px" data-i18n="raume.konzept.sub">Diese Räume sind Raummetaphern — Beschreibungen der Weltstruktur. Manche sind live, manche konzeptionell, manche noch in der Begriffsprüfung. Sie sind auf der Weltkarte (LEITSTAND) als Ellipsen sichtbar.</div>
</div>
<div class="rv-grid">${cards}</div>
<div style="padding:0 20px">${hZwischenraum}${hPlatStruktur}</div>

<!-- Provenienz: Von Wesen gebaute Strukturen -->
<div id="rv-provenienz" style="padding:12px 20px;border-top:1px solid var(--b10);margin-top:8px">
  <div style="font-size:0.52rem;color:#1a3a2a;letter-spacing:.1em;margin-bottom:8px" data-i18n="raume.prov.head">VON WESEN GEBAUT</div>
  <div id="rv-prov-items" style="display:flex;flex-direction:column;gap:4px">
    <div style="font-size:0.55rem;color:#1a3a2a" data-i18n="raume.prov.empty">Noch keine Wesen-Strukturen — wird leer bleiben bis der Einzug stattfindet.</div>
  </div>
</div>
<script>
(function(){
  function ladeDbRooms(){
    var cont=document.getElementById('rv-db-rooms');
    if(!cont)return;
    fetch('/api/raeume?limit=20').then(function(r){return r.json();}).then(function(d){
      var rooms=d.raeume||[];
      if(!rooms.length){cont.innerHTML='<div style="font-size:0.52rem;color:#1a3a2a">Keine Räume gefunden.</div>';return;}
      cont.innerHTML=rooms.map(function(rm){
        var posts=rm.post_count||0;
        var themen=rm.themen_count||0;
        var status=rm.status||'aktiv';
        var statusCol=status==='aktiv'?'var(--g2)':'var(--t-sub)';
        var isZwischen=rm.slug==='zwischenraum';
        var desc=rm.beschreibung||'';
        var discursLink=posts>0?'<button onclick="switchView(&apos;diskurs&apos;);diskursLaden()" style="font-size:0.45rem;padding:2px 6px;background:none;border:1px solid var(--b10);color:var(--t-sub);cursor:pointer;margin-top:4px">Diskurs →</button>':'';
        var archLink=posts>0?'<button onclick="switchView(&apos;archaeologie&apos;)" style="font-size:0.45rem;padding:2px 6px;background:none;border:1px solid var(--b10);color:var(--t-sub);cursor:pointer;margin-top:4px;margin-left:4px">Archäologie →</button>':'';
        var badge=isZwischen
          ?'<span style="font-size:0.45rem;padding:1px 4px;background:#07122a;color:#3a6a9a;border:1px solid var(--rim);margin-left:4px">ZWISCHENRAUM</span>'
          :'<span style="font-size:0.45rem;padding:1px 4px;background:var(--g1);color:var(--ta3);border:1px solid #0e3020;margin-left:4px">DATENSTRUKTUR</span>';
        return '<div style="background:var(--surface);border:1px solid var(--rim);border-radius:4px;padding:10px 12px">'
          +'<div style="display:flex;align-items:center;gap:0;margin-bottom:4px">'
          +'<span style="font-size:0.65rem;font-weight:700;color:'+statusCol+'">'+rm.name+'</span>'
          +badge
          +'</div>'
          +'<div style="font-size:0.5rem;color:#3a5a6a;margin-bottom:6px">'+desc+'</div>'
          +'<div style="display:flex;gap:12px;font-size:0.48rem;color:#1a4a3a">'
          +'<span>Posts: <strong style="color:var(--ta2)">'+posts+'</strong></span>'
          +(themen?'<span>Themen: <strong style="color:var(--ta2)">'+themen+'</strong></span>':'')
          +'</div>'
          +(posts>0?'<div style="margin-top:4px">'+discursLink+archLink+'</div>':'<div style="font-size:0.46rem;color:#1a3a2a;margin-top:4px">Noch keine Posts in diesem Raum.</div>')
          +'</div>';
      }).join('');
    }).catch(function(){if(cont)cont.innerHTML='<div style="font-size:0.52rem;color:#3a2a1a">API nicht erreichbar.</div>';});
  }
  function ladeProv(){
    fetch('/api/provenienz').then(r=>r.json()).then(d=>{
      var cont=document.getElementById('rv-prov-items');
      if(!cont)return;
      var items=d.provenienz||[];
      if(!items.length){cont.innerHTML='<div style="font-size:0.55rem;color:#1a3a2a">Noch keine Wesen-Strukturen.</div>';return;}
      cont.innerHTML=items.map(function(p){
        var von=(p.erstellt_von||'').replace('namelessAI_','');
        var zeit=p.created_at?new Date(p.created_at).toLocaleDateString('de'):'';
        var farbe=p.typ==='raum'?'var(--t-sub)':'#2a7a5a';
        return '<div style="padding:4px 0;border-bottom:1px solid #040c12;display:flex;gap:8px;align-items:center">'
          +'<span style="color:'+farbe+';font-size:0.52rem;font-family:monospace">'+p.typ.toUpperCase()+'</span>'
          +'<span style="color:#4a8a7a;font-size:0.58rem">'+p.name+'</span>'
          +'<span style="color:#1a3a5a;font-size:0.5rem">⬡'+von+'</span>'
          +'<span style="color:#1a3a2a;font-size:0.48rem;margin-left:auto">'+zeit+'</span>'
          +'</div>';
      }).join('');
    }).catch(function(){});
  }
  document.addEventListener('DOMContentLoaded',function(){
    var obs=new MutationObserver(function(){
      if(document.getElementById('view-raume')?.style.display!=='none'){ladeDbRooms();ladeProv();}
    });
    var el=document.getElementById('view-raume');
    if(el)obs.observe(el,{attributes:true,attributeFilter:['style']});
  });
})();
</script>
</div></div>`;
}

