  // ---- WESEN + CYBERLINGE ----
  window.admWesenLaden = function() {
    var el = document.getElementById("adm-we-liste");
    if(!el) return;
    el.innerHTML='<div class="adm-empty">Lade…</div>';
    fetch("/api/admin/cyberlinge",{headers:{"Authorization":tok()}})
      .then(function(r){return r.json();}).then(function(d){
        var items = d.cyberlinge || [];
        if(!items.length){el.innerHTML='<div class="adm-empty">Keine Cyberlinge.</div>';return;}
        el.innerHTML = items.map(function(c){
          var bars = [
            ["Hunger",c.hunger,"#3a8a4a"],
            ["Durst",c.durst,"#3a5a9a"],
            ["Energie",c.energie,"#8a7a2a"],
            ["Stimmung",c.stimmung,"#6a3a9a"],
            ["Gesundheit",c.gesundheit,"#8a3a3a"]
          ].map(function(bar){
            var pct = Math.round((bar[1]||0)*100);
            return '<div class="adm-cl-row">'
              +'<div class="adm-cl-label">'+bar[0]+'</div>'
              +'<div class="adm-cl-bar-bg"><div class="adm-cl-bar-fill" style="width:'+pct+'%;background:'+bar[2]+'"></div></div>'
              +'<div class="adm-cl-val">'+pct+'%</div>'
              +'<input class="adm-cl-input" type="number" min="0" max="100" value="'+pct+'" id="cl-'+c.entity_id+'-'+bar[0].toLowerCase()+'">'
              +'</div>';
          }).join("");
          return '<div class="adm-wesen-card">'
            +'<div class="adm-wesen-name">'+admEsc(c.entity_id)
            +'<span style="font-size:0.55rem;font-weight:normal;color:#'+(c.status==="lebendig"?"2a8a5a":"8a2a2a")+';margin-left:8px">'+admEsc(c.status||"")+'</span>'
            +'<span style="font-size:0.55rem;color:#2a5a7a;margin-left:8px">Tod: '+admEsc(String(c.tode||0))+'×</span>'
            +'</div>'
            +bars
            +'<button class="adm-btn adm-btn-blue" style="margin-top:8px;font-size:0.55rem" onclick="admCyberlingSetzen(&apos;'+c.entity_id+'&apos;)">Werte übernehmen</button>'
            +(c.letzte_entscheidung?'<div style="font-size:0.55rem;color:#1a4a6a;margin-top:6px">Letzte Aktion: '+admEsc(c.letzte_entscheidung)+'</div>':'')
            +'</div>';
        }).join("");
      }).catch(function(){el.innerHTML='<div class="adm-empty">Fehler.</div>';});
  };

  window.admCyberlingSetzen = function(entityId) {
    var felder = ["hunger","durst","energie","stimmung","gesundheit"];
    var body = {};
    felder.forEach(function(f){
      var inp = document.getElementById("cl-"+entityId+"-"+f);
      if(inp) body[f] = Math.min(1, Math.max(0, parseFloat(inp.value)/100));
    });
    fetch("/api/admin/cyberlinge/"+entityId,{method:"PATCH",headers:{"Authorization":tok(),"Content-Type":"application/json"},body:JSON.stringify(body)})
      .then(function(){admWesenLaden();});
  };

