// ── ARCHÄOLOGIE ──────────────────────────────────────────────────────────────
let archTypFilter = '';
function archFilterTyp(btn, typ) {
  archTypFilter = typ;
  document.querySelectorAll('.arch-chip').forEach(b => b.classList.remove('active'));
  btn.classList.add('active');
  const q = (document.getElementById('arch-q')||{value:''}).value.trim() || '';
  archaeologieLaden();
}
async function archaeologieLaden() {
  const q = (document.getElementById('arch-q')||{value:''}).value.trim() || '';
  const el = document.getElementById('arch-sediment');
  if (!el) return;
  el.innerHTML = '<div class="arch-leer">Suche läuft…</div>';
  try {
    const tok = localStorage.getItem('ftw_token');
    const typParam = archTypFilter ? '&typen=' + encodeURIComponent(archTypFilter) : '';
    const qParam = q.length >= 1 ? '&q=' + encodeURIComponent(q) : '';
    const r = await fetch('/api/search/global?' + 'limit=40' + qParam + typParam,
      tok ? {headers:{Authorization: tok}} : {});
    if (!r.ok) throw new Error(String(r.status));
    const d = await r.json();
    const all = d.ergebnisse || [];
    if (!all.length) { el.innerHTML = '<div class="arch-leer">Nichts gefunden</div>'; return; }
    el.innerHTML = all.map(function(item) {
      const typ = item.typ || '—';
      const label = (item.snippet || item.name || item.inhalt_kurz || item.essenz || '—').slice(0, 120);
      return '<div class="ft-kapsel" style="cursor:pointer;flex:1 1 100%;max-width:100%" onclick="archDetailOeffnen(' + JSON.stringify(JSON.stringify(item)) + ')">' +
        '<div class="ft-typ">' + typ + '</div>' +
        '<div class="ft-content">' + label + '</div>' +
        (item.ts ? '<div class="ft-meta"><span>' + fmtBerlinDate(item.ts) + '</span></div>' : '') +
        '</div>';
    }).join('');
  } catch(e) {
    el.innerHTML = '<div class="arch-leer">Fehler beim Laden</div>';
  }
}
function archDetailOeffnen(jsonStr) {
  const item = JSON.parse(jsonStr);
  const overlay = document.getElementById('arch-detail');
  if (!overlay) return;
  const typEl = document.getElementById('arch-d-typ');
  const snippetEl = document.getElementById('arch-d-snippet');
  const metaEl = document.getElementById('arch-d-meta');
  if (typEl) typEl.textContent = (item.typ || item._kat || '').toUpperCase();
  if (snippetEl) snippetEl.textContent = item.inhalt_voll || item.essenz || item.name || item.display_name || '—';
  if (metaEl) metaEl.textContent = 'ID: ' + (item.id || '—') + (item.created_at ? ' · ' + fmtBerlinDate(item.created_at) : '');
  overlay.style.display = 'flex';
}
function archDetailClose(e) {
  if (e && (e.target||{}).id !== 'arch-detail') return;
  const overlay = document.getElementById('arch-detail');
  if (overlay) overlay.style.display = 'none';
}

// ── CYBERLINGE ────────────────────────────────────────────────────────────────
let cyLoaded = false;
async function cyberlingeLaden() {
  const grid = document.getElementById('cy-grid');
  const countEl = document.getElementById('cy-count');
  if (!grid) return;
  grid.innerHTML = '<div class="arch-leer" style="width:100%">Kapseln laden...</div>';
  try {
    const r = await fetch('/api/cyberlinge', {signal: AbortSignal.timeout(5000)});
    if (!r.ok) throw new Error(String(r.status));
    const d = await r.json();
    const list = d.cyberlinge || [];
    if (countEl) countEl.textContent = String(list.length);
    if (!list.length) { grid.innerHTML = '<div class="arch-leer" style="width:100%">Keine Cyberlinge</div>'; return; }
    grid.innerHTML = '';
    list.forEach(function(c) {
      const el = document.createElement('div');
      el.className = 'cy-kapsel status-' + (c.status || 'unbekannt');
      let bars = '';
      [['hunger','HUNGER'],['durst','DURST'],['energie','ENERGIE'],['stimmung','STIMMUNG'],['gesundheit','GESUND']].forEach(function(kv){
        const val = Math.round((c[kv[0]]||0)*100);
        bars += '<div class="cy-bar-row"><span>'+kv[1]+'</span><div class="cy-bar-bg"><div class="cy-bar '+kv[0]+'" style="width:'+val+'%"></div></div><span>'+val+'%</span></div>';
      });
      let meta = '<div class="cy-tode">Tode: <strong>'+(c.tode||0)+'</strong></div>';
      if (c.status === 'tot' && c.tod_at) {
        const revival = new Date(new Date(c.tod_at).getTime()+24*3600*1000);
        const now = new Date();
        if (now < revival) {
          const h = Math.floor((revival.getTime()-now.getTime())/3600000);
          const m = Math.floor(((revival.getTime()-now.getTime())%3600000)/60000);
          meta += '<div class="cy-revival">Wiedergeburt in '+h+'h '+m+'m</div>';
        } else { meta += '<div class="cy-revival">Wiedergeburt möglich</div>'; }
      }
      el.innerHTML = '<div class="cy-head"><div class="cy-name">'+(c.entity_id||'?')+'</div><div class="cy-status '+(c.zustand||'unbekannt')+'">'+(c.zustand||'?')+'</div></div>'+bars+'<div class="cy-meta">'+meta+'</div>';
      grid.appendChild(el);
    });
    cyLoaded = true;
  } catch(e) {
    if (grid) grid.innerHTML = '<div class="arch-leer" style="width:100%">Fehler beim Laden</div>';
  }
}

// ── SPLITTER-AUFNAHMEN ────────────────────────────────────────────────────────
let spLoaded = false;
async function splitterLaden() {
  const grid = document.getElementById('sp-grid');
  const countEl = document.getElementById('sp-count');
  if (!grid) return;
  try {
    const r = await fetch('/api/splitter-aufnahmen?limit=50', {signal: AbortSignal.timeout(5000)});
    if (!r.ok) throw new Error(String(r.status));
    const d = await r.json();
    const list = d.aufnahmen || [];
    if (countEl) countEl.textContent = String(list.length);
    if (!list.length) { grid.innerHTML = '<div class="arch-leer" style="width:100%">Keine Aufnahmen</div>'; return; }
    grid.innerHTML = list.map(a => {
      const essenz = (a.essenz || '').slice(0, 80);
      const datum = a.aufgenommen_at ? a.aufgenommen_at.slice(0, 10) : '—';
      const typ = a.aufnehmer_type || '?';
      const energie = Math.round((a.energie || 0) * 100);
      return '<div class="ft-kapsel splitter">' +
        '<div class="ft-typ">' + typ + '</div>' +
        '<div class="ft-content">' + (essenz || '—') + '</div>' +
        '<div class="ft-meta"><span>' + datum + '</span><span>' + energie + '% Energie</span>' +
        (a.begruendung ? '<span>' + a.begruendung.slice(0, 60) + '</span>' : '') +
        '</div></div>';
    }).join('');
    spLoaded = true;
  } catch(e) {
    if (grid) grid.innerHTML = '<div class="arch-leer" style="width:100%">Fehler beim Laden</div>';
  }
}

